local x,y,unN,pos2,typ,dir,pla=GetBattlefieldVehicleInfo(n)
if x and not pla then
if typ==Nx.AiT then
cnt=1
dir=dir/PI*180
oy=oy/1.5
ox,oy=ox*cos(dir)+oy*sin(dir),(ox*-sin(dir)+oy*cos(dir))*1.5
ox=x*100+ox
oy=y*100+oy
break
