function Nx.ToB:Upd()
local dat=Nx:GDTB()
local svd=dat[self.Nam]
local f=self.Frm
f:ClearAllPoints()
local ali="TOPRIGHT"
if not svd["AlignR"] then
ali="TOPLEFT"
if svd["AlignB"] then
ali="BOTTOMLEFT"
end
else
if svd["AlignB"] then
ali="BOTTOMRIGHT"
end
end
f:SetPoint(ali,0,0)
local sca=svd["Size"]/self.Siz2
local spa=(svd["Space"] or 0)/sca
local ste=self.Siz2+spa
local xst=ste
local yst=0
if svd["Vert"] then
xst=0
yst=ste
end
local xof=0
local yof=0
for n,too in ipairs(self.Too) do
local but1=too.But2
if but1 then
but1:SeP1("TOPLEFT",xof,-yof)
end
xof=xof+xst
yof=yof+yst
end
if not svd["Vert"] then
xof=xof-spa
else
yof=yof-spa
end
f:SetWidth(max(xof,self.Siz2))
f:SetHeight(max(yof,self.Siz2))
f:SetScale(sca)
end
