function Nx.Inf:CLT()
local ch=Nx.CuC
local lvl=tonumber(ch["Level"] or 0)
if lvl<MAX_PLAYER_LEVEL then
local lvH=difftime(time(),ch["LvlTime"])/3600
local xp=max(1,ch["XP"]-ch["LXP"])
local lvT=(ch["XPMax"]-ch["XP"])/(xp/lvH)
if lvT<100 then
return "",format("%.1f",lvT)
end
return "|cff808080","?"
end
end
