elseif typ=="CH" then
local i=self:GeV(ite.V)
ist=format("%s  |cffffff80%s",ist,i)
elseif typ=="F" then
local i=self:GeV(ite.V)
ist=format("%s  |cffffff80%s",ist,i)
elseif typ=="I" then
local i=self:GeV(ite.V)
ist=format("%s  |cffffff80%s",ist,i)
elseif typ=="S" then
local s=self:GeV(ite.V)
ist=format("%s  |cffffff80%s",ist,s)
elseif typ=="Frm" then
end
end
lis:ItS(2,ist)
end
elseif type(ite)=="string" then
local col2="|cff9f9f9f"
