function Nx.Lis:Res1(wid,hei)
local f=self.Frm
local hdH=self.HdH
local liH=self:GLH()
local paW=1
local paH=0
if self.ShA then
hei=self.Num*liH+hdH+paH*2
local las=self.Top+self.Vis-1
las=min(las,self.Num)
local stN=1
local cNu=1
wid=paW*2
local ofX=0
for k,col3 in ipairs(self.Col) do
local mCW=col3.Wid
for lin1=self.Top,las do
if self.Off then
ofX=self.Off[lin1] or 0
end
mCW=max(mCW,self.Str[stN]:GetWidth()+ofX)
stN=stN+1
end
stN=stN+(self.Vis*cNu-stN+1)
wid=wid+mCW
cNu=cNu+1
self.SSW=wid
self.SSH=hei
end
end
wid=max(self.MiW,wid)
hei=max(self.MiH,hei)
f:SetWidth(wid)
f:SetHeight(hei)
local sfr=self.SeF2
sfr:SetWidth(wid-10)
hei=max(hei-hdH,1)
self.Vis=floor((hei-paH*2)/liH)
self.Vis=max(self.Vis,0)
local hf=self.HdF
if hf then
hf:SetWidth(wid)
hf:SetHeight(hdH)
end
local x=0
local clW=wid-paW*2
for k,col3 in ipairs(self.Col) do
local coW=min(col3.Wid,clW)
col3.ClW=coW
local hfs=col3.FSt
if hfs then
hfs:SetPoint("TOPLEFT",paW+x,0)
hfs:SetWidth(coW)
end
x=x+col3.Wid
clW=clW-col3.Wid
end
self:CrS()
self:CrB()
end
function Nx.Map:IOMD(but)
local map=this.NxM1
map:CaC3()
map.ClF=this
map.ClT2=this.NXType
map.ClI=this.NXData
local shi=IsShiftKeyDown()
if but=="LeftButton" then
local cat1=floor((this.NXType or 0)/1000)
if cat1==2 and shi then
if map.BGIN>0 then
local _,_,_,str=strsplit("~",map.BGM)
local _,_,_,st2=strsplit("~",this.NXData)
if str~=st2 then
Nx.Tim:Fir("BGInc")
end
end
map.BGM=this.NXData
map.BGIN=map.BGIN+1
UIErrorsFrame:AddMessage("Inc " .. map.BGIN,1,1,1,1)
Nx.Tim:Sta("BGInc",1.5,map,map.BGIST)
else
if map:IDC() then
if cat1==3 then
map:GM_OG()
end
else
this=map.Frm
map:OMD(but)
end
end
else
if but=="RightButton" then
local typ=this.NXType
if typ then
local i=floor(typ/1000)
if i==1 then
map:BPL()
map.PIM:Ope()
elseif i==2 then
Nx.Tim:Fir("BGInc")
map.BGM=this.NXData
map.BGIM:Ope()
elseif i==3 then
map:GMO(this.NXData,typ)
elseif i==9 then
Nx.Que:IOMD(this)
end
end
else
this=map.Frm
map:OMD(but)
end
end
end
