function Nx.Map:Rou(poi2)
if #poi2==0 then
return
end
local tm=GetTime()
local rou={}
for n,pt in ipairs(poi2) do
pt.Y=pt.Y/1.5
end
if #poi2>1 then
local x=poi2[1].X
local y=poi2[1].Y
if x==poi2[#poi2].X and y==poi2[#poi2].Y then
tremove(poi2)
end
end
local x,y=self:GZP(self.MaI,self.PlX,self.PlY)
y=y/1.5
while #poi2>0 do
local clD=999999999
local clI
for n,pt in ipairs(poi2) do
local dis=(x-pt.X) ^ 2+(y-pt.Y) ^ 2
if dis<clD then
clD=dis
clI=n
end
end
local pt=tremove(poi2,clI)
local r={}
tinsert(rou,r)
r.Nam=pt.Nam
r.X=pt.X
r.Y=pt.Y
r.Wei=pt.Wei or 1
x=pt.X
y=pt.Y
end
local x=rou[1].X
local y=rou[1].Y
if x~=rou[#rou].X or y~=rou[#rou].Y then
local r={}
r.X=x
r.Y=y
tinsert(rou,r)
end
local len=self:RoL(rou)
for n=1,5 do
local swa=self:RoO(rou)
if not swa then
break
end
end
local sca=self:GWZS(self.MaI)
local len=self:RoL(rou)
Nx.prt("Routed %s nodes, %d yards in %.1f secs",#rou,len*sca*4.575,GetTime()-tm)
return rou
end
