local lef=f:GetLeft()
local rgt=f:GetRight()
local bw=self.BoW
local bh=self.BoH
if x>=rgt-bw then
if y>=top-bh then
return 6
elseif y<=bot1+bh then
return 10
end
return 2
elseif x<lef+bw then
if y>=top-bh then
return 5
elseif y<=bot1+bh then
return 9
end
return 1
elseif y<=bot1+bh then
return 8
elseif y>=top-bh then
return 4
end
else
