else
assert(false)
end
end
end
function Nx.prV(msg,v)
local prt=Nx.prt
if v==nil then
prt(msg.." nil")
elseif type(v)=="boolean" then
prt(msg.." "..tostring(v))
elseif type(v)=="number" then
prt(format("%s #%d (0x%x)",msg,v,v))
elseif type(v)=="string" then
local s=gsub(v,"%%","%%%%")
prt(msg.. " '" .. s .."'")
elseif type(v)=="table" then
Nx.prT(msg,v)
else
prt(msg.." ? "..tostring(v))
end
end
