function Nx.Que:CaD3(n1,n2)
local Nx=Nx
local Que=Nx.Que
local qop=Nx:GQO()
local Map=Nx.Map
local map=Map:GeM(1)
local px=map.PlX
local py=map.PlY
local plL2=UnitLevel("player")
local cur1=self.CuQ
if not cur1 then
return
end
for n=n1,n2 do
local cur=cur1[n]
if not cur then
break
end
local qi=cur.QI
local qId=cur.QId
local id=qId>0 and qId or cur.Tit
local qSt=Nx:GeQ(id)
local qWa=(qSt=="W")
local que=cur.Q
cur.Pri=1
cur.Dis1=999999999
cur.COI=-1
if que then
local cnt=(cur.CoM or cur.LBC==0) and 0 or 99
for qOb=0,cnt do
local quO1
if qOb==0 then
quO1=(qi>0 or cur.Par) and que[3] or que[2]
else
quO1=que[qOb+3]
end
if not quO1 then
break
end
if bit.band(cur.TrM2,bit.lshift(1,qOb))>0 then
local nam,zon=self:GOP(que,quO1)
if zon then
local mId=Map.NTMI[zon]
if mId then
local x,y=self:GCOP(quO1,mId,px,py)
local dis=((x-px) ^ 2+(y-py) ^ 2) ^ .5
if dis<cur.Dis1 then
cur.COI=qOb
cur.Dis1=dis
end
cur["OX"..qOb]=x
cur["OY"..qOb]=y
cur["OD"..qOb]=dis
end
end
end
end
local pri1=0
if cur.CoM then
pri1=qop.NXWPriComplete*8
else
local l=min(plL2-cur.Lev,10)
l=max(l,-10)
pri1=l*qop.NXWPriLevel
end
cur.Pri=1-pri1/2010
cur.InZ=Que:ChS(map.RMI,qId)
end
end
end
function Nx.Que:GOR(que,str)
local Que=Nx.Que
local nam,zon,loc=Que:UnO(str)
if not zon then
return
end
local x1=100
local y1=100
local x2=0
local y2=0
local cnt
if strbyte(str,loc)==32 then
cnt=floor((#str-loc)/4)
local x,y
for loN1=loc+1,loc+cnt*4,4 do
x,y=Que:ULPO(str,loN1)
x1=min(x1,x)
y1=min(y1,y)
x2=max(x2,x)
y2=max(y2,y)
end
elseif strbyte(str,loc)==33 then
x1,y1=Que:ULPR(str,loc+1)
x2,y2=x1,y1
else
loc=loc-1
cnt=floor((#str-loc)/4)
for loN1=loc+1,loc+cnt*4,4 do
local lo1=strsub(str,loN1,loN1+3)
local x,y,w,h=Que:ULR(lo1)
x1=min(x1,x)
y1=min(y1,y)
x2=max(x2,x+w/1002*100)
y2=max(y2,y+h/668*100)
end
end
return x1,y1,x2,y2
end
function Nx.Que.Lis:ToW(qId,qIn,qOb,shi)
local Que=Nx.Que
local Map=Nx.Map
if qOb==0 and not shi then
