end
end
elseif strbyte(daS)==33 then
else
for n=1,#daS,2 do
local npI=(strbyte(daS,n)-35)*221+(strbyte(daS,n+1)-35)
local npS=Nx.NPCD[npI]
local fac2=strbyte(npS,1)-35
