function Nx.Tra:MaP(tra2,sMI,srX,srY,dMI,dsX,dsY,taT1)
if not self.GOp["MapRouteUse"] then
return
end
if UnitOnTaxi("player") then
return
end
local Map=Nx.Map
local win1=Map.MWI
local srI1=win1[sMI]
sMI=srI1.EMI or sMI
local dsI1=win1[dMI]
dMI=dsI1.EMI or dMI
local x=dsX-srX
local y=dsY-srY
local taD=(x*x+y*y) ^ .5
if sMI==dMI and taD<500/4.575 then
return
end
local rid1=Nx.War.SkR
local co1=Map:ITCZ(sMI)
local co2=Map:ITCZ(dMI)
local lvl=UnitLevel("player")
local coF=GetSpellInfo(self.CFN)
self.FlM=rid1>=225 and(co1==3 or co1==4 and coF)
local spe1=2/4.5
if rid1<75 then
spe1=1/4.5
elseif rid1<150 then
spe1=1.6/4.5
elseif self.FlM then
spe1=2.5/4.5
end
self.Spe=spe1
if co1==co2 then
if rid1>=300 and self.FlM then
return
end
self.VMI={}
local pat={}
local no1={}
no1.MaI=sMI
no1.X=srX
no1.Y=srY
tinsert(pat,no1)
local no2={}
no2.MaI=dMI
no2.X=dsX
no2.Y=dsY
tinsert(pat,no2)
local wat1=10
repeat
local noC=#pat
for n=1,#pat-1 do
local no1=pat[n]
local no2=pat[n+1]
if not no1.NoS1 then
if no1.MaI~=no2.MaI then
local coD1,con=self:FiC5(no1.MaI,no1.X,no1.Y,no2.MaI,no2.X,no2.Y)
local flD,fpa=self:FiF3(no1.MaI,no1.X,no1.Y,no2.MaI,no2.X,no2.Y)
if coD1 and(not fpa or coD1<flD) then
if con then
local an1=math.deg(math.atan2(srX-con.StX,srY-con.StY))
local an2=math.deg(math.atan2(srX-con.EnX,srY-con.EnY))
local ang=abs(an1-an2)
ang=ang>180 and 360-ang or ang
if con.SMI~=no1.MaI then
no1.NoS1=true
end
local nam=format("Connection: %s to %s",Nx.MITN[con.SMI],Nx.MITN[con.EMI1])
local nod={}
nod.NoS1=true
nod.MaI=con.SMI
nod.X=con.StX
nod.Y=con.StY
nod.Nam=nam
nod.Tex1="Interface\\Icons\\Spell_Nature_FarSight"
tinsert(pat,n+1,nod)
self.VMI[con.SMI]=true
if ang>90 then
nod.Die=true
end
local nod={}
nod.MaI=con.EMI1
nod.X=con.EnX
nod.Y=con.EnY
nod.Nam=nam
nod.Tex1="Interface\\Icons\\Spell_Nature_FarSight"
tinsert(pat,n+2,nod)
end
else
if fpa then
tinsert(pat,n+1,fpa[1])
tinsert(pat,n+2,fpa[2])
end
end
else
local diD1=((no1.X-no2.X) ^ 2+(no1.Y-no2.Y) ^ 2) ^ .5
local flD,fpa=self:FiF3(no1.MaI,no1.X,no1.Y,no2.MaI,no2.X,no2.Y)
if fpa and flD<diD1 then
tinsert(pat,n+1,fpa[1])
tinsert(pat,n+2,fpa[2])
end
end
end
end
wat1=wat1-1
if wat1<0 then
break
end
until noC==#pat
for n=2,#pat-1 do
local no1=pat[n]
if not no1.Die then
local x,y=no1.X,no1.Y
local t1={}
t1.TaT=taT1
t1.TX1=x
t1.TY1=y
t1.TX2=x
t1.TY2=y
t1.TMX=x
t1.TMY=y
t1.TaT1=no1.Tex1
t1.TaN1=no1.Nam
if no1.Fli then
t1.Mod="F"
end
tinsert(tra2,t1)
end
end
end
end
