function Nx.Map:CFW(frm,bx,by,w,h,dir)
local bw=w
local bh=h
local clW=self.MaW
local clH=self.MaH
local sca=self.ScD
local x=(bx-self.MPXD)*sca+clW/2
local y=(by-self.MPYD)*sca+clH/2
local tX1=0
local tX2=1
local vx0=x-bw*.5
local vx1=vx0
local vx2=vx0+bw
if vx1<0 then
vx1=0
tX1=(vx1-vx0)/bw
end
if vx2>clW then
vx2=clW
tX2=(vx2-vx0)/bw
end
w=vx2-vx1
if w<.3 then
if self.ScF1~=frm then
frm:Hide()
else
frm:SetWidth(.001)
end
return false
end
local tY1=0
local tY2=1
local vy0=y-bh*.5
local vy1=vy0
local vy2=vy0+bh
if vy1<0 then
vy1=0
tY1=(vy1-vy0)/bh
end
if vy2>clH then
vy2=clH
tY2=(vy2-vy0)/bh
end
h=vy2-vy1
if h<.3 then
if self.ScF1~=frm then
frm:Hide()
else
frm:SetWidth(.001)
end
return false
end
frm:SetPoint("TOPLEFT",vx1,-vy1-self.TiH)
frm:SetWidth(w)
frm:SetHeight(h)
if dir==0 then
frm.tex:SetTexCoord(tX1,tX2,tY1,tY2)
else
local t1x,t1y,t2x,t2y,t3x,t3y,t4x,t4y
tX1=tX1-.5
tX2=tX2-.5
tY1=tY1-.5
tY2=tY2-.5
local co=cos(dir)
local si=sin(dir)
t1x=tX1*co+tY1*si+.5
t1y=tX1*-si+tY1*co+.5
t2x=tX1*co+tY2*si+.5
t2y=tX1*-si+tY2*co+.5
t3x=tX2*co+tY1*si+.5
t3y=tX2*-si+tY1*co+.5
t4x=tX2*co+tY2*si+.5
t4y=tX2*-si+tY2*co+.5
frm.tex:SetTexCoord(t1x,t1y,t2x,t2y,t3x,t3y,t4x,t4y)
end
frm:Show()
return true
end
function Nx.Map.Doc:MDF1()
if Nx.Tic % self.UpM1~=0 then
return
end
if not self.Win1 then
return
end
self.UpM1=30
if NxData.DebugDock then
Nx.prt("Dock %s",#self.MMF1)
end
local mm=getglobal("Minimap")
local mmC=getglobal("TimeManagerClockButton")
local win=self.Win1
local win2=win.Frm
local buL=win2:GetFrameLevel()+1
local cLv=buL+1
local sCL=Nx.U_SCL
local str1=win2:GetFrameStrata()
local min4=self.GOp["MMButWinMinimize"]
local cx,cy=win:GCO()
local cw,ch=win:GeS2()
local coC=min4 and 1 or self.GOp["MapMMButColumns"]
local coS1=0
local coE=coC-1
local coA=1
local spa1=self.GOp["MapMMButSpacing"]
local yAd=spa1
local y=cy+6
local s=self.GOp["MapMMButCorner"]
if s=="TopRight" or s=="BottomRight" then
coE=-coE
coA=-1
end
if s=="BottomLeft" or s=="BottomRight" then
yAd=-yAd
y=cy-6
end
local col3=coS1
local boS=win:GBS()
local baX=boS+17
local baY=y
local inR
for n,f in ipairs(self.MMF1) do
if f:IsVisible() then
local w=f:GetWidth()
if w>0 then
local sc=32/max(w,32)
if inR then
inR=false
col3=coS1
y=y+yAd
end
if min4 and n>1 then
col3=0
y=baY
buL=1
cLv=1
sc=.1
end
local x=baX+col3*spa1
f:SetParent(win2)
f:ClearAllPoints()
if f==mmC then
sc=sc*1.5
end
f:SetPoint("CENTER",win2,"TOPLEFT",x/sc,-y/sc)
f:SetScale(sc)
f:SetFrameStrata(str1)
f:SetFrameLevel(buL)
sCL(f,cLv)
if col3==coE then
inR=true
end
col3=col3+coA
end
elseif f:IsShown() then
f:Show()
end
end
if not win.MoS then
local x=win2:GetLeft()
win:SeS(34,11)
end
end
