local r1=rou[n]
local r2=rou[n+1]
local n2=n+len
local r3=rou[n2]
local r4=rou[n2+1]
if r1.Dis+r3.Dis>
((r1.X-r3.X) ^ 2+(r1.Y-r3.Y) ^ 2) ^ .5+((r2.X-r4.X) ^ 2+(r2.Y-r4.Y) ^ 2) ^ .5 then
