function Nx.Que:RQL()
local qcn=GetNumQuestLogEntries()
local opt=self.GOp
local cur1=self.CuQ
local olS=GetQuestLogSelection()
local laC
local qId1={}
self.QId1=qId1
local paS
if self.RQE==qcn then
for cur2,cur in ipairs(cur1) do
local qi=cur.QI
if qi>0 then
local tit,lev,tag,grC,isH,isC,isC1=GetQuestLogTitle(qi)
tit=self:ExT(tit)
if cur.Tit==tit then
local cha1
if isC1==1 and not cur.Com2 then
Nx.prt("Quest Complete '%s'",tit)
if opt["QSndPlayCompleted"] then
self:PlaySound()
end
if opt["QWRemoveComplete"] then
self.Wat:ReW(cur.QId,cur.QI)
self.Wat:Upd()
cha1=false
else
cha1=true
end
end
local lbC=GetNumQuestLeaderBoards(qi)
for n=1,lbC do
local des1,typ,don=GetQuestLogLeaderBoard(n,qi)
if des1~=cur[n] or don~=cur[n+100] then
if opt["QWAddChanged"] then
if cha1==nil then
cha1=true
end
end
local s1,_,olC1=strfind(cur[n] or "",": (%d+)/")
if s1 then
olC1=tonumber(olC1)
end
local s1,_,neC=strfind(des1,": (%d+)/")
if s1 then
neC=tonumber(neC)
end
if don or(olC1 and neC and neC>olC1) then
self:Cap(cur2,n)
end
laC=cur
paS=true
end
end
if cha1 and opt["QWAddChanged"] then
self.Wat:Add(cur2)
end
end
end
end
else
paS=true
end
local fak={}
local n=1
while cur1[n] do
local cur=cur1[n]
if not cur.Got or cur.Par then
table.remove(cur1,n)
else
fak[cur.Q]=cur
n=n+1
end
end
self.ReQ={}
local hea="?"
self.RQE=qcn
local ind=#cur1+1
for qn=1,qcn do
local tit,lev,tag,grC,isH,isC,isC1,isD=GetQuestLogTitle(qn)
if isH then
hea=tit or "?"
else
tit=self:ExT(tit)
SelectQuestLogEntry(qn)
local qDe,qOb=GetQuestLogQuestText()
local qId,qLe=self:GLIL(qn)
assert(qId)
local que=self.ITQ[qId]
local lbC=GetNumQuestLeaderBoards(qn)
local cur=que and fak[que]
if not cur then
cur={}
cur1[ind]=cur
cur.Ind=ind
ind=ind+1
else
cur.Got=nil
cur.Ind=ind
if que then
self.Tra1[qId]=0
self:TOM(qId,0,true)
end
end
qId1[qId]=cur
cur.Q=que
cur.QI=qn
cur.QId=qId or 0
cur.Hea1=hea
cur.Tit=tit
cur.ObT=qOb
cur.DeT1=qDe
cur.Lev=lev
cur.ReL2=qLe
cur.Tag=tag
cur.GCn=grC or 0
cur.PaS1=grC or 1
if tag=="Dungeon" or tag=="Heroic" then
cur.PaS1=5
elseif tag=="Raid" then
cur.PaS1=10
end
cur.TaS=self.TaN2[tag] or ""
cur.Dai=isD
if isD then
cur.TaS="$" .. cur.TaS
end
cur.CaS1=GetQuestLogPushable()
cur.Com2=isC1
local lef=GetQuestLogTimeLeft()
if lef then
cur.TiE=time()+lef
cur.HiP1=true
end
cur.ItL2,cur.ItI1,cur.ItC1=GetQuestLogSpecialItemInfo(qn)
cur.Pri=1
cur.Dis1=999999999
cur.LBC=lbC
for n=1,lbC do
local des1,typ,don=GetQuestLogLeaderBoard(n,qn)
cur[n]=des1
cur[n+100]=don
end
local mas=0
local end1=que and(que[3] or que[2])
if(isC1 and end1) or lbC==0 or(cur.Got and que[2]) then
mas=1
else
for n=1,99 do
local don
if n<=lbC then
don=cur[n+100]
end
local obj=que and que[3+n]
if not obj then
break
end
if obj and not don then
mas=mas+bit.lshift(1,n)
end
end
end
cur.TrM2=mas
self.ReQ[tit]=cur
if que then
self:CCNM(cur,que)
end
end
end
if self.GOp["QPartyShare"] and self.Wat.BSP:GeP() then
local pq=self.PaQ
for plN,pda in pairs(pq) do
for qId,qT in pairs(pda) do
local que=self.ITQ[qId]
local cur=qId1[qId]
if cur then
local s=format("\n|cff8080f0%s|r",plN)
if not cur.PaD1 then
cur.PaD1=""
cur.PaN1="\n|cfff080f0Me"
cur.PaC1=0
cur.PaC2=cur.Com2
for n,cnt in ipairs(qT) do
cur[n+200]=cur[n+100]
cur[n+400]="\n|cfff080f0Me" .. s
end
end
cur.PaD1=cur.PaD1 .. s
cur.PaN1=cur.PaN1 .. s
cur.PaC1=cur.PaC1+1
cur.PaC2=cur.PaC2 and qT.Com2
local mas=(cur.PaC2 or #qT==0) and 1 or 0
for n,cnt in ipairs(qT) do
local tot=qT[n+100]
local des1,don=self:CaD2(que,n,cnt,tot)
don=cur[n+200] and don
cur[n+200]=don
cur.PaD1=cur.PaD1 .. "\n " .. des1
cur[n+400]=cur[n+400] .. " " .. des1
if not don then
mas=mas+bit.lshift(1,n)
end
end
cur.TrM2=mas
elseif que then
local nam,sid,lvl=self:Unp(que[1])
local cur={}
cur.Got=true
cur.Par=plN
cur.PaD1=format("\n|cff8080f0%s|r",plN)
cur.PaN1=cur.PaD1
cur.Q=que
cur.QI=0
cur.QId=qId
cur.Hea1="Party, " .. plN
cur.Tit=nam
cur.ObT=""
cur.Lev=lvl
cur.PaS1=1
cur.TaS=""
cur.Com2=qT.Com2
cur.Pri=1
cur.Dis1=999999999
self:CCNM(cur,que)
tinsert(cur1,cur)
cur.Ind=#cur1
cur.LBC=#qT
local mas=(qT.Com2 or #qT==0) and 1 or 0
for n,cnt in ipairs(qT) do
local tot=qT[n+100]
cur[n],cur[n+100]=self:CaD2(que,n,cnt,tot)
cur[n+400]=cur.PaN1
if not cur[n+100] then
mas=mas+bit.lshift(1,n)
end
end
cur.TrM2=mas
end
end
end
end
for cur2,cur in ipairs(cur1) do
if cur.PaC1 then
cur.CoM=cur.PaC2
for n,des1 in ipairs(cur) do
cur[n+300]=cur[n+200]
end
else
cur.CoM=cur.Com2
for n,des1 in ipairs(cur) do
cur[n+300]=cur[n+100]
end
end
end
if laC then
self.QLC=self:FCFO(laC)
end
SelectQuestLogEntry(olS)
self:SoQ()
if paS then
self:PSS()
end
self.Map.Gui:UMI1()
end
