end
function Nx.Map:CFTL(frm,bx,by,w,h)
local sca=self.ScD
local bw=w*sca
local clW=self.MaW
local x=(bx-self.MPXD)*sca+clW/2
local tX1=0
local tX2=1
local vx1=x
local vx2=x+bw
if vx1<0 then
vx1=0
tX1=(vx1-x)/bw
end
if vx2>clW then
vx2=clW
tX2=(vx2-x)/bw
end
w=vx2-vx1
if w<.3 then
if self.ScF1~=frm then
frm:Hide()
else
frm:SetWidth(.001)
end
return false
end
local bh=h*sca
local clH=self.MaH
local y=(by-self.MPYD)*sca+clH/2
local tY1=0
local tY2=1
local vy1=y
local vy2=y+bh
if vy1<0 then
vy1=0
tY1=(vy1-y)/bh
end
if vy2>clH then
vy2=clH
tY2=(vy2-y)/bh
end
h=vy2-vy1
if h<.3 then
if self.ScF1~=frm then
frm:Hide()
else
frm:SetWidth(.001)
end
return false
end
frm:SetPoint("TOPLEFT",vx1,-vy1-self.TiH)
if w<=1.2 then
w=self.Si1
if w<=0 then
frm:SetWidth(.001)
return
end
end
if h<=1.2 then
h=self.Si1
if h<=0 then
frm:SetWidth(.001)
return
end
end
frm:SetWidth(w)
frm:SetHeight(h)
frm.tex:SetTexCoord(tX1,tX2,tY1,tY2)
frm:Show()
return true
end
