end
if opt["MapShowPalsInCities"] then
self:UPI(self.PaI,map,"IconPlyrG")
end
else
if opt["MapShowOthersInZ"] then
self:UPI(self.ZPI,map,"IconPlyrZ")
end
self:UPI(self.PaI,map,"IconPlyrG")
