dat[n+1000000]=self.BuD[i+1000000]
dat[n+2000000]=self.BuD[i+2000000]
dat[n+3000000]=self.BuD[i+3000000]
dat[n+8000000]=self.BuD[i+8000000]
dat[n+9000000]=self.BuD[i+9000000]
end
