function Nx.Map:UpO1(maI,bri,noU)
local wzo=self:GWZ(maI)
if wzo and wzo.Cit then
return
end
local txF=wzo and wzo.Ove1 or ""
local ove1=Nx.Map.ZoO[txF]
local une
if not noU and(not ove1 or not self.ShU) then
if not(wzo and wzo.Exp) then
une=true
end
ove1=self.CuO1
txF=self.COTF
end
if not ove1 then
return
end
local bW,bH
local txI
local tPW,tFW,tPH,tFH
local pat="Interface\\Worldmap\\" .. txF .. "\\"
local alp=self.BaA
local uEA=self.LOp.NXUnexploredAlpha
local zsc=self:GWZS(maI)/10
for txN,whS in pairs(ove1) do
local lev1=0
local brt=bri
txN=pat .. txN
local oX,oY,txW,txH,mod1=strsplit(",",whS)
txW=tonumber(txW)
txH=tonumber(txH)
oX=tonumber(oX)
oY=tonumber(oY)
if une then
if oX<0 then
oX=oX+10000
else
brt=uEA
lev1=1
end
end
bW=ceil(txW/256)
bH=ceil(txH/256)
txI=1
for bY=0,bH-1 do
if bY<bH-1 then
tPH=256
tFH=256
else
tPH=mod(txH,256)
if tPH==0 then
tPH=256
end
tFH=16
while tFH<tPH do
tFH=tFH*2
end
end
for bX=0,bW-1 do
if bX<bW-1 then
tPW=256
tFW=256
else
tPW=mod(txW,256)
if tPW==0 then
tPW=256
end
tFW=16
while tFW<tPW do
tFW=tFW*2
end
end
local f=self:GINI(lev1)
local wx,wy=self:GWP(maI,(oX+bX*256)/1002*100,(oY+bY*256)/668*100)
if self:CFTL(f,wx,wy,tFW*zsc,tFH*zsc) then
f.tex:SetTexture(mod1 and txN or txN .. txI)
f.tex:SetVertexColor(brt,brt,brt,alp)
end
txI=txI+1
end
end
end
self.Lev=self.Lev+2
end
