function Nx.Map:CFWC(frm,bx,by,w,h)
local bw=w
local bh=h
local clW=self.MaW
local clH=self.MaH
local sca=self.ScD
local x=(bx-self.MPXD)*sca+clW/2
local y=(by-self.MPYD)*sca+clH/2
local tX1=0
local tX2=1
local vx0=x-bw*.5
local vx1=vx0
local vx2=vx0+bw
if vx1<0 then
vx1=0
tX1=(vx1-vx0)/bw
end
if vx2>clW then
vx2=clW
tX2=(vx2-vx0)/bw
end
w=vx2-vx1
if w<.3 then
if self.ScF1~=frm then
frm:Hide()
else
frm:SetWidth(.001)
end
return false
end
local tY1=0
local tY2=1
local vy0=y-bh*.5
local vy1=vy0
local vy2=vy0+bh
if vy1<0 then
vy1=0
tY1=(vy1-vy0)/bh
end
if vy2>clH then
vy2=clH
tY2=(vy2-vy0)/bh
end
h=vy2-vy1
if h<.3 then
if self.ScF1~=frm then
frm:Hide()
else
frm:SetWidth(.001)
end
return false
end
frm:SetPoint("TOPLEFT",vx1,-vy1-self.TiH)
frm:SetWidth(w)
frm:SetHeight(h)
frm.tex:SetTexCoord(tX1*.9+.05,tX2*.9+.05,tY1*.9+.05,tY2*.9+.05)
frm:Show()
return true
end
