local sz=max(self.MaW,self.MaH)
if dis*self.Sca/sz>10 then
stT2=1
end
local st=abs(self.StT)
if st>0 and st<stT2 then
stT2=st
end
self.StT=stT2
if dis<.25 then
self.MPXD=self.MPX
self.MPYD=self.MPY
end
if abs(1/self.ScD-1/self.Sca)<.01 then
self.ScD=self.Sca
