Nx:SeQ(ite.UDa,s,time())
if ite:GetChecked() then
self:CPD1(ite.UDa)
end
self:UGIM()
self.GIMC:Upd()
local map=Nx.Map:GeM(1)
map.Gui:UMI1()
end
self.GIMICT[n]=coM1:AdI1(0,"?",fun,self)
self.GIMICT[n]:SetChecked()
end
local inM=Nx.Men:Cre(frm)
self.GIMI=inM
self.GIMII=maM:ASM(inM,"Quest Info (shift click - goto)...")
self.GIMIIT={}
for n=1,29 do
