function Nx.Map:UPH()
local Map=Nx.Map
local his=Map.PlH
local tm=GetTime()
local sca=self.BaS
local x=his.LaX-self.MLX
local y=his.LaY-self.MLY
local moD=(x*x+y*y) ^ .5
if moD>self.GOp["MapTrailDist"]*sca then
his.LaX=self.MLX
his.LaY=self.MLY
his.Tim1=tm
local next=his.Nex
local o=next*4-3
his[o]=GetTime()
his[o+1]=self.PlX
his[o+2]=self.PlY
his[o+3]=self.PlD
if next>=his.Cnt then
next=0
end
his.Nex=next+1
end
local siz=min(max(4*self.ScD*self.BaS,3),25)
local faT=self.GOp["MapTrailTime"]
for n=1,his.Cnt*4,4 do
local sec=his[n]
local tmd=tm-sec
if tmd<faT then
local x=his[n+1]
local y=his[n+2]
local dir=his[n+3]
local f=self:GINI()
if self:CFW(f,x,y,siz,siz,dir) then
f.tex:SetTexture("Interface\\AddOns\\Carbonite\\Gfx\\Map\\IconCircleFade")
local a=(faT-tmd)/faT*.9
f.tex:SetVertexColor(1,0,0,a)
end
end
end
end
