if not cur.Got and Nx:GeQ(qId)=="W" then
local flg=0
if cur.Com2 then
flg=flg+1
end
local str=format("%04x%c%c",qId,flg+35,cur.LBC+35)
for n=1,cur.LBC do
local _,_,cnt,tot=strfind(cur[n],": (%d+)/(%d+)")
cnt=tonumber(cnt)
tot=tonumber(tot)
if cnt and tot then
if cnt>200 then
cnt=200
end
else
cnt=0
if cur[n+100] then
cnt=1
end
tot=0
end
str=str .. format("%02x%02x",cnt,tot)
end
seS=seS .. str
if #seS>80 then
tinsert(dat,seS)
seS=""
end
end
end
if #seS>0 or #dat==0 then
tinsert(dat,seS)
end
Nx.Tim:Sta("QSendParty",0,self,self.PST)
