function Nx.NXMiniMapBut:Mov(x,y)
local but1=NXMiniMapBut
local mm=getglobal("Minimap")
local l=mm:GetLeft()+70
local b=mm:GetBottom()+70
x=x-l
y=y-b
local ang=atan2(y,x)
local r=(x ^ 2+y ^ 2) ^ .5
r=max(r,79)
r=min(r,110)
x=r*cos(ang)
y=r*sin(ang)
but1:SetPoint("TOPLEFT",mm,"TOPLEFT",x+54,y-54)
but1:SetUserPlaced(true)
end
